-- 1) Cau hoi on nhanh cua tung hoat dong (giao vien sua o trang Hoat dong). [] = khong co quiz.
alter table activities add column if not exists quiz jsonb not null default '[]';

-- Nap cau hoi soan san (BAN NHAP, giao vien duyet) - CHI cho hoat dong CHUA co quiz, khong de len ban giao vien da sua.
update activities set quiz = '[{"id":"act_kh_01_q1","prompt":"Trên lá khoai môn, giọt nước tròn và lăn đi. Vì sao?","options":["Lá có lớp phấn mỏng, không thấm nước","Lá khoai môn rất nóng","Nước trên lá khoai nặng hơn"],"correct":0,"explanation":"Lớp phấn làm lá không thấm nước nên giọt nước co tròn lại."},{"id":"act_kh_01_q2","prompt":"Muốn so sánh các lá cho công bằng, em nên làm thế nào?","options":["Nhỏ giọt nước giống nhau lên mỗi lá","Lá nào nhỏ giọt to, lá nào nhỏ giọt bé","Chỉ cần nhìn một lá"],"correct":0,"explanation":"Giữ mọi thứ giống nhau, chỉ đổi loại lá, mới biết khác biệt là do lá."}]'::jsonb where id = 'act_kh_01' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kh_02_q1","prompt":"Chòm Bắc Đẩu có mấy ngôi sao sáng xếp hình cái gáo?","options":["7 ngôi sao","3 ngôi sao","12 ngôi sao"],"correct":0,"explanation":"Bắc Đẩu gồm 7 ngôi sao sáng, xếp như cái gáo múc nước."},{"id":"act_kh_02_q2","prompt":"Lúc nào dễ nhìn thấy sao nhất?","options":["Buổi tối trời quang, ít mây","Buổi trưa nắng to","Buổi tối có nhiều mây đen"],"correct":0,"explanation":"Trời tối và quang mây thì ánh sao không bị che."}]'::jsonb where id = 'act_kh_02' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kh_03_q1","prompt":"Bọt khí nổi lên khi đun nước sôi chủ yếu là gì?","options":["Hơi nước","Bụi trong nước","Khói từ bếp"],"correct":0,"explanation":"Nước ở đáy nồi nóng nhất, biến thành hơi nước rồi nổi lên thành bọt."},{"id":"act_kh_03_q2","prompt":"Khi quan sát nồi nước đang đun, em cần nhớ điều gì?","options":["Đứng xa vừa đủ và có người lớn ở gần","Ghé sát mặt vào nồi cho rõ","Thò tay vào thử độ nóng"],"correct":0,"explanation":"Hơi nước và nước sôi có thể gây bỏng rất nặng."}]'::jsonb where id = 'act_kh_03' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kh_04_q1","prompt":"Cầu vồng thường xuất hiện khi nào?","options":["Có nắng chiếu qua những giọt mưa","Trời tối không có trăng","Trời khô hanh, không có nước"],"correct":0,"explanation":"Ánh nắng đi qua giọt mưa bị tách thành nhiều màu."},{"id":"act_kh_04_q2","prompt":"Có một thắc mắc \"vì sao\", cách nào tốt để tìm câu trả lời?","options":["Hỏi thầy cô, người lớn hoặc tra sách","Tự đoán rồi coi là đúng luôn","Bỏ qua vì không quan trọng"],"correct":0,"explanation":"Kiểm tra với nguồn đáng tin giúp em biết mình đoán đúng hay sai."}]'::jsonb where id = 'act_kh_04' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kt_01_q1","prompt":"Trước khi tháo một đồ vật, em cần làm gì?","options":["Xin phép người lớn và chọn đồ cũ không quan trọng","Tháo ngay điện thoại của bố mẹ","Dùng búa đập cho nhanh"],"correct":0,"explanation":"Đồ cũ, được phép thì hỏng cũng không sao và an toàn hơn."},{"id":"act_kt_01_q2","prompt":"Lò xo trong bút bi bấm dùng để làm gì?","options":["Đẩy ruột bút thụt vào sau khi bấm","Làm bút nặng hơn","Giữ cho mực không bị khô"],"correct":0,"explanation":"Bấm thì lò xo bị nén; bấm lần nữa lò xo đẩy ruột bút thụt vào."}]'::jsonb where id = 'act_kt_01' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kt_02_q1","prompt":"Ghế lung lay vì con ốc ở chân bị lỏng. Em nên làm gì?","options":["Siết lại con ốc bằng tua vít","Sơn lại ghế","Vứt ghế đi ngay"],"correct":0,"explanation":"Nhiều hỏng hóc nhỏ chỉ cần siết lại hoặc chêm cho chắc."},{"id":"act_kt_02_q2","prompt":"Đồ nào em KHÔNG nên tự sửa khi chưa có người lớn?","options":["Ổ cắm điện bị hở dây","Dây giày bị rối","Chân bàn bị kênh"],"correct":0,"explanation":"Đồ điện có thể gây giật, phải để người lớn hoặc thợ sửa."}]'::jsonb where id = 'act_kt_02' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kt_03_q1","prompt":"Trên sơ đồ đường nước, mũi tên dùng để chỉ điều gì?","options":["Chiều nước chảy","Màu của nước","Giá tiền của ống nước"],"correct":0,"explanation":"Mũi tên cho người xem biết nước đi từ đâu đến đâu."},{"id":"act_kt_03_q2","prompt":"Vẽ sơ đồ xong, bước cuối nên làm gì?","options":["So lại với thực tế xem có đúng không","Tô màu thật đẹp","Cất đi, không cần xem lại"],"correct":0,"explanation":"So với thực tế giúp em phát hiện chỗ vẽ sai."}]'::jsonb where id = 'act_kt_03' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kt_04_q1","prompt":"Cách nào giúp mô hình cây cầu đứng vững hơn?","options":["Buộc chặt các mối nối, làm chân đế rộng","Dùng càng ít que càng tốt","Để các que lỏng lẻo"],"correct":0,"explanation":"Mối nối chắc và chân đế rộng giúp mô hình không bị đổ."},{"id":"act_kt_04_q2","prompt":"Vì sao nên đặt thử một vật nhẹ lên mô hình?","options":["Để kiểm tra mô hình chịu lực được không","Để trang trí cho đẹp","Để mô hình nặng hơn khi mang đi"],"correct":0,"explanation":"Thử chịu lực là cách kỹ sư kiểm tra công trình."}]'::jsonb where id = 'act_kt_04' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_nl_01_q1","prompt":"Cây có lá vàng ở gốc, đất khô và nứt. Cây có thể đang thiếu gì?","options":["Thiếu nước","Thừa nước","Thiếu bóng tối"],"correct":0,"explanation":"Đất khô nứt và lá vàng là dấu hiệu cây thiếu nước."},{"id":"act_nl_01_q2","prompt":"Nên tưới cây vào lúc nào trong ngày?","options":["Sáng sớm hoặc chiều mát","Giữa trưa nắng gắt","Lúc nào cũng như nhau"],"correct":0,"explanation":"Trưa nắng, nước bốc hơi nhanh và cây dễ bị sốc nóng."}]'::jsonb where id = 'act_nl_01' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_nl_02_q1","prompt":"Loại đất nào thường hợp trồng rau?","options":["Đất nâu sẫm, tơi xốp và hơi ẩm","Đất khô cứng, nứt nẻ","Cát khô hoàn toàn"],"correct":0,"explanation":"Đất tơi, ẩm giữ được nước và không khí cho rễ."},{"id":"act_nl_02_q2","prompt":"Đất \"tơi xốp\" nghĩa là gì?","options":["Đất có nhiều khe hở, bóp nhẹ là vỡ ra","Đất dính chặt thành cục cứng","Đất toàn là đá"],"correct":0,"explanation":"Khe hở trong đất giữ không khí và nước cho rễ cây."}]'::jsonb where id = 'act_nl_02' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_nl_03_q1","prompt":"Con gà đứng riêng, ít ăn, xù lông. Có thể nó đang làm sao?","options":["Có thể bị mệt hoặc bị ốm","Đang rất khỏe","Đang đói nên đòi ăn"],"correct":0,"explanation":"Đứng riêng, bỏ ăn, xù lông thường là dấu hiệu vật nuôi không khỏe."},{"id":"act_nl_03_q2","prompt":"Thấy vật nuôi có dấu hiệu ốm, em nên làm gì?","options":["Báo cho bố mẹ hoặc người lớn","Tự cho uống thuốc của người","Không cần để ý"],"correct":0,"explanation":"Người lớn hoặc cán bộ thú y mới biết cách chữa đúng."}]'::jsonb where id = 'act_nl_03' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_nl_04_q1","prompt":"Loại rác nào có thể tái chế hoặc bán ve chai?","options":["Vỏ chai nhựa","Thức ăn thừa","Giấy ăn đã dùng"],"correct":0,"explanation":"Chai nhựa có thể làm chậu cây hoặc bán ve chai."},{"id":"act_nl_04_q2","prompt":"Túi ni lông đã dùng nên xử lý thế nào?","options":["Gom lại, bỏ đúng nơi thu gom","Đốt ngay tại chỗ","Vứt xuống suối"],"correct":0,"explanation":"Đốt ni lông sinh khói độc; vứt xuống suối làm bẩn nguồn nước."}]'::jsonb where id = 'act_nl_04' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kd_01_q1","prompt":"Gạo 10.000đ, rau 5.000đ, trứng 12.000đ, mắm muối 3.000đ. Cả bữa hết bao nhiêu?","options":["30.000đ","25.000đ","35.000đ"],"correct":0,"explanation":"10.000 + 5.000 + 12.000 + 3.000 = 30.000đ."},{"id":"act_kd_01_q2","prompt":"Bữa ăn 30.000đ cho 5 người. Mỗi người khoảng bao nhiêu?","options":["6.000đ","15.000đ","3.000đ"],"correct":0,"explanation":"30.000 : 5 = 6.000đ mỗi người."}]'::jsonb where id = 'act_kd_01' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kd_02_q1","prompt":"Vòng tay bán 5.000đ, tốn 2.000đ tiền hạt. Mỗi chiếc lãi bao nhiêu?","options":["3.000đ","7.000đ","2.000đ"],"correct":0,"explanation":"Lãi = giá bán - chi phí = 5.000 - 2.000 = 3.000đ."},{"id":"act_kd_02_q2","prompt":"Câu quảng cáo tốt nên thế nào?","options":["Ngắn, nói rõ điểm hay của sản phẩm","Thật dài, kể mọi thứ","Nói xấu sản phẩm của người khác"],"correct":0,"explanation":"Câu ngắn, rõ điểm hay thì người nghe dễ nhớ."}]'::jsonb where id = 'act_kd_02' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kd_03_q1","prompt":"Cô bán rau hay chào khách và cho thêm hành. Việc đó giúp gì?","options":["Khách vui và hay quay lại mua","Cô bán được giá gấp đôi","Không giúp gì"],"correct":0,"explanation":"Khách quen quay lại là điều quan trọng với người bán hàng."},{"id":"act_kd_03_q2","prompt":"Khi quan sát người bán hàng, em nên chú ý điều gì?","options":["Cách họ chào khách, giới thiệu và tính tiền","Họ mặc áo màu gì","Họ dùng điện thoại loại gì"],"correct":0,"explanation":"Đó là những kỹ năng chính của nghề bán hàng."}]'::jsonb where id = 'act_kd_03' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_kd_04_q1","prompt":"Mỗi ngày bớt 3.000đ tiền quà vặt. Sau 7 ngày em để dành được bao nhiêu?","options":["21.000đ","10.000đ","30.000đ"],"correct":0,"explanation":"3.000 x 7 = 21.000đ."},{"id":"act_kd_04_q2","prompt":"Mục tiêu tiết kiệm nào cụ thể nhất?","options":["Để dành 20.000đ trong tuần này để mua sách","Em sẽ cố gắng tiết kiệm","Khi nào có tiền thì tiết kiệm"],"correct":0,"explanation":"Mục tiêu có số tiền, thời hạn và lý do thì dễ làm theo."}]'::jsonb where id = 'act_kd_04' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_sk_01_q1","prompt":"Khi đọc viết, mắt nên cách vở khoảng bao nhiêu?","options":["Khoảng 30 cm","Khoảng 5 cm","Khoảng 1 mét"],"correct":0,"explanation":"Cách khoảng 30 cm giúp mắt đỡ mỏi, tránh cận thị."},{"id":"act_sk_01_q2","prompt":"Góc học tập thế nào là tốt cho mắt?","options":["Đủ ánh sáng, ví dụ gần cửa sổ","Càng tối càng dễ tập trung","Đèn chiếu thẳng vào mắt"],"correct":0,"explanation":"Học chỗ thiếu sáng làm mắt phải điều tiết nhiều, nhanh mỏi."}]'::jsonb where id = 'act_sk_01' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_sk_02_q1","prompt":"Bị bỏng nhẹ, việc đầu tiên nên làm là gì?","options":["Xả nước mát lên vết bỏng khoảng 15 phút","Bôi kem đánh răng","Chườm đá lạnh"],"correct":0,"explanation":"Nước mát làm dịu và giảm tổn thương; kem đánh răng, đá lạnh làm vết bỏng nặng hơn."},{"id":"act_sk_02_q2","prompt":"Bị đứt tay nhẹ, nên làm gì?","options":["Rửa sạch, ấn nhẹ cho cầm máu rồi băng lại","Để nguyên cho tự khô","Bôi đất lên vết thương"],"correct":0,"explanation":"Vết thương sạch và được băng sẽ ít bị nhiễm trùng."}]'::jsonb where id = 'act_sk_02' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_sk_02b_q1","prompt":"Khi hỏi thăm người thân đang mệt, điều quan trọng nhất là gì?","options":["Lắng nghe và giúp một việc nhỏ","Hỏi thật nhanh rồi đi chơi","Bảo họ tự lo"],"correct":0,"explanation":"Được lắng nghe và giúp đỡ làm người thân thấy được quan tâm."},{"id":"act_sk_02b_q2","prompt":"Bà bị đau lưng. Việc nhỏ nào em có thể giúp?","options":["Rót nước ấm và nhắc bà nghỉ ngơi","Nhờ bà bê đồ nặng giúp em","Tự lấy thuốc cho bà uống"],"correct":0,"explanation":"Thuốc phải do người lớn hoặc nhân viên y tế quyết định."}]'::jsonb where id = 'act_sk_02b' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_sk_03_q1","prompt":"Ngồi học lâu, vì sao nên đứng dậy vận động nhẹ?","options":["Để mắt đỡ mỏi, người bớt mệt","Để được nghỉ học sớm","Không có tác dụng gì"],"correct":0,"explanation":"Vận động nhẹ giúp máu lưu thông, mắt và lưng được nghỉ."},{"id":"act_sk_03_q2","prompt":"Bao lâu thì nên đứng dậy vận động một lần?","options":["Sau khoảng 45 phút đến 1 giờ ngồi học","Cứ 2 phút một lần","Học xong cả ngày mới nghỉ"],"correct":0,"explanation":"Nghỉ ngắn sau mỗi tiết học là vừa, không làm đứt mạch học."}]'::jsonb where id = 'act_sk_03' and quiz = '[]'::jsonb;
update activities set quiz = '[{"id":"act_nt_01_q1","prompt":"Trong hoạt động vẽ nhanh, điều gì quan trọng nhất?","options":["Ghi lại khoảnh khắc em nhớ, không cần đẹp","Vẽ thật đẹp như họa sĩ","Vẽ đúng tỉ lệ từng chi tiết"],"correct":0,"explanation":"Vẽ nhanh là để lưu lại cảm xúc, không phải để thi vẽ đẹp."},{"id":"act_nt_01_q2","prompt":"Đặt tên cho bức vẽ giúp gì?","options":["Nói lên điều em muốn kể trong tranh","Làm tranh nặng hơn","Không giúp gì"],"correct":0,"explanation":"Tên tranh giúp người xem hiểu câu chuyện của em."}]'::jsonb where id = 'act_nt_01' and quiz = '[]'::jsonb;
