update activities set quiz = '[{"id":"act_nt_03_q1","prompt":"Chụp từ sát mặt đất nhìn lên gọi là góc chụp gì?","options":["Góc thấp","Góc cao","Góc ngang"],"correct":0,"explanation":"Góc thấp làm vật trông to và lạ hơn bình thường."},{"id":"act_nt_03_q2","prompt":"Chụp một vật từ nhiều góc khác nhau giúp em điều gì?","options":["Thấy vật quen thuộc theo cách mới lạ","Tốn pin hơn","Ảnh chắc chắn bị mờ"],"correct":0,"explanation":"Đổi góc nhìn là một cách sáng tạo của người chụp ảnh."}]'::jsonb where id = 'act_nt_03' and quiz = '[]'::jsonb;
