-- 2) Bai lam quiz: toi da 1 lan / (em, hoat dong, ngay); KHONG tinh vao ho so so thich.
create table if not exists quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  activity_id text not null references activities(id) on delete cascade,
  date date not null,
  quiz_version text not null,
  answers jsonb not null default '[]', -- [{questionId, chosen, correct}]
  n_correct smallint not null,
  n_questions smallint not null check (n_questions > 0 and n_correct between 0 and n_questions),
  started_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz not null default now(),
  unique (student_id, activity_id, date)
);
create index if not exists idx_quiz_attempts_student on quiz_attempts(student_id, date);
alter table quiz_attempts enable row level security; -- khong policy: chi server (service role)

-- 3) Bai doi chieu RIASEC (O*NET Mini-IP) cho MAU CON lop giao vien bat.
alter table class_groups add column if not exists riasec_enabled boolean not null default false;
create table if not exists riasec_attempts (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null unique references students(id) on delete cascade,
  items_version text not null,
  answers jsonb not null, -- {id cau: 1-5}
  started_at timestamptz,
  completed_at timestamptz not null default now()
);
alter table riasec_attempts enable row level security; -- khong policy: chi server (service role)

insert into schema_migrations (version) values ('20261018b_quiz_riasec')
on conflict (version) do nothing;

-- Kiem tra: 48 hoat dong co quiz, 2 bang moi
select (select count(*) from activities where jsonb_array_length(quiz) > 0) as hoat_dong_co_quiz,
       to_regclass('public.quiz_attempts') as bang_quiz, to_regclass('public.riasec_attempts') as bang_riasec;

